package com.camisetas360.recommendation.repository;

import com.camisetas360.recommendation.model.Recommendation;

import java.util.List;

/**
 * Data access abstraction for persisting and retrieving AI recommendations.
 */
public interface RecommendationRepository {

    /**
     * Persists a recommendation for an order.
     *
     * @param orderId associated order identifier
     * @param customerEmail customer email
     * @param recommendedItemsJson JSON string containing recommended items
     * @param explanation text explanation generated by AI
     * @return persisted {@link Recommendation}
     */
    Recommendation save(long orderId, String customerEmail, String recommendedItemsJson, String explanation);

    /**
     * Finds recommendations by order id.
     *
     * @param orderId order identifier
     * @return list of recommendations
     */
    List<Recommendation> findByOrderId(long orderId);
}

